mapper.select:
select distinct sdl.ITEM_CODE id, sdl.ITEM_VALUE text from SYS_DATADICT_LIST sdl inner join SYS_DATADICT_LIST_LINK sdll on sdl.ITEM_CODE = sdll.ITEM_CODE
and sdll.LINKED_DICT_CODE = #{dict_code_parent}
and sdl.DICT_CODE = #{dict_code_child} and sdll.DICT_CODE = #{dict_code_child}
and TRIM(sdll.LINKED_ITEM_CODE) = TRIM(#{item_code_parent})
sdl.ITEM_VALUE like '%' || #{search} || '%'
ORDER BY sdl.ITEM_CODE asc

SELECT NVL(SUM(A.O_AMT),0) FROM BOK_BALANCE A,BOK_SUBJECT B,BOK_BOOKSET C WHERE A.BOOKSET_ID = C.BOOKSET_ID AND B.BOOKSET_ID = C.BOOKSET_ID_TMPL AND A.SUBJECT_NO = B.SUBJECT_NO /**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 start**/
AND B.BASE_SUBJECT_NATURE = 'HQCK_BJ'
AND B.BASE_SUBJECT_NATURE = 'XJ'
/**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 end**/ AND A.SUBJECT_LEVEL = '1'
AND A.BOOKSET_ID in
#{item}
AND TO_CHAR(A.BALANCE_DATE,'yyyy-MM-dd') = #{mdate,jdbcType=VARCHAR}

SELECT NVL(SUM(A.O_AMT),0) FROM BOK_BALANCE A,BOK_SUBJECT B,BOK_BOOKSET C WHERE A.BOOKSET_ID = C.BOOKSET_ID AND B.BOOKSET_ID = C.BOOKSET_ID_TMPL AND A.SUBJECT_NO = B.SUBJECT_NO /**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 start**/
AND B.BASE_SUBJECT_NATURE = 'HQCK_BJ'
AND B.BASE_SUBJECT_NATURE = 'XJ'
/**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 end**/
AND A.SUBJECT_LEVEL = '1'
AND A.BOOKSET_ID in
#{item}
AND TO_CHAR(A.BALANCE_DATE,'yyyy-MM-dd') = #{mdate,jdbcType=VARCHAR}

    	SELECT
    		NVL(SUM(A.O_HAPPEN_AMT),0)
    	FROM TRD_VOUCH_DEAL_DETAIL A,BOK_SUBJECT B,BOK_BOOKSET C,TRD_VOUCH_DEAL D
		WHERE 1=1

			AND  A.BOOKSET_ID in

				#{item}


    	AND	C.BOOKSET_ID = A.BOOKSET_ID
    	AND	B.BOOKSET_ID = C.BOOKSET_ID_TMPL
    	AND	A.SUBJECT_NO = B.SUBJECT_NO
		/**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 start**/


				AND B.BASE_SUBJECT_NATURE = 'HQCK_BJ'


				AND B.BASE_SUBJECT_NATURE = 'XJ'


		/**update by yinya on 2022-03-24 新会计引擎升级，兼容新老科目体系的科目性质 end**/
    	AND D.TRADE_ID = A.TRADE_ID
    	AND	A.CD_FLAG = #{crdrFlg,jdbcType=VARCHAR}
    	AND TO_CHAR(D.BOOK_DATE,'yyyy-MM-dd') >= #{vdate,jdbcType=VARCHAR}
    	AND TO_CHAR(D.BOOK_DATE,'yyyy-MM-dd') <= #{mdate,jdbcType=VARCHAR}

select DECODE( jx.trantype, '752', 'F14', '751', 'F14', '300','F11', '410','F12', '761', 'F34','760','F34', '200','F10','100','F10','107','F10','105','F10','108','F10','103','F10','104','F10' ) as finprodType, /*金融产品类型*/ jx.tanum as tradeId,/*交易编号*/ jx.settledate as settleDate,/*结算日期*/ jx.trantype as ps,/*交易类型*/ DECODE(jx.trantype, '761', jx.currencycode2, jx.currencycode) as tradeCcy,/*交易币种*/ jx.fxrate as fxrate, /*交易汇率 */ CASE WHEN jx.trantype in ('300','410','200','100','107','105','108','103','104') THEN jx.cash WHEN jx.trantype = '760' THEN jx.PRINCIPAL WHEN jx.trantype = '761' THEN jx.CASH2 ELSE 0 END as buyTradeAmt,/*买入端交易金额*/ CASE WHEN jx.trantype IN ('752','751') THEN jx.intatmat ELSE 0 END as recInt, /*收息*/ DECODE(jx.trantype, '761', jx.currencycode, jx.currencycode2) AS sellCcy,/*卖出币种*/ jx.fxrate2 as fxrate2, /*空方交易汇率 */ CASE WHEN jx.trantype IN ('752','751') THEN jx.intatmat2 ELSE 0 END as payInt, /*付息*/ CASE WHEN jx.trantype IN ('300','410') THEN jx.cash2 WHEN jx.trantype = '760' THEN jx.PRINCIPAL2 WHEN jx.trantype = '761' THEN jx.CASH ELSE 0 END as sellTradeAmt /*卖出端交易金额*/ from JXT_TRAN_BASIC jx where jx.post_status = 'P' and jx.trantype in ('752','751','300','410','761','760','200','100','107','105','108','103') and jx.settledate >= TO_DATE(#{vdate},'yyyy-MM-dd') and jx.settledate <= TO_DATE(#{mdate},'yyyy-MM-dd') and exists ( select bookset_id, busi_no, busi_table, bookset_date, book_date, happen_date, is_accounted, book_id, create_user, create_dept, create_time, update_user, update_time, inv_aim, inv_aim_method from BOK_DEAL_ACCOUNTING acct where acct.busi_no = jx.tanum AND acct.BOOKSET_ID in
#{item}
)

select quot_unit quoUnit/*报价单位*/ from MST_EXCHARGE_QUOTE where basis_cyy in
#{item}
and quot_cyy = #{bCcy} and trade_date <= TO_DATE(#{vdate},'yyyy-MM-dd') and trade_date >= TO_DATE(#{mdate},'yyyy-MM-dd')
